SET time_zone='+00:00';SET SESSION lock_wait_timeout=5;SET SESSION innodb_lock_wait_timeout=5;SET SESSION MAX_EXECUTION_TIME=5000;
SELECT m.id meeting_id,m.revision,m.needs_generation,m.minutes_revision_id,m.element_set_id,i.status actor_status,t.id task_id,t.state task_state,t.last_error,t.output_kind,t.output_id,e.id execution_id,e.state execution_state,e.request_hash,e.marked_at,e.finished_at,o.id operation_id,o.state operation_state,o.external_result_id,o.reconcile_epoch,o.reconcile_owner,o.reconcile_expires_at,o.next_check_at,r.id permit_id,r.settled_at,(SELECT COUNT(*) FROM generation_candidate c WHERE c.task_id=t.id) candidate_count FROM external_execution e JOIN durable_task t ON t.id=e.task_id JOIN meeting m ON m.id=t.subject_id JOIN enterprise_identity i ON i.enterprise_id=m.owner_id JOIN external_operation o ON o.id=e.operation_id LEFT JOIN model_reservation r ON r.execution_id=e.id WHERE e.id IN ('b1050c2b-ac1c-4abc-b302-b34d7b68758d','fd323464-54c7-4d80-ae93-ac0cd7925663');
